import { Effect, Option, Schema } from "effect";
import { BrowserAnalyticsPreference, BrowserPrivacySignals } from "./schema";

export const ANALYTICS_CONSENT_COOKIE = "krakstack_analytics_consent";
export const ANALYTICS_NOTICE_VERSION = "1";
const changedEvent = "krakstack:analytics-consent";
const lifetime = 180 * 24 * 60 * 60 * 1000;

const codec = Schema.StringFromUriComponent.pipe(
  Schema.decodeTo(Schema.fromJsonString(BrowserAnalyticsPreference)),
);

const readCookie = (cookie: string) =>
  cookie
    .split(";")
    .map((part) => part.trim())
    .find((part) => part.startsWith(`${ANALYTICS_CONSENT_COOKIE}=`))
    ?.slice(ANALYTICS_CONSENT_COOKIE.length + 1);

export const analyticsPreference = (cookie: string, now = Date.now()) => {
  const value = readCookie(cookie);
  if (!value) return undefined;
  // Cookie values are URI encoded at the browser boundary. Invalid values fail closed.
  const decoded = Schema.decodeUnknownOption(codec)(value);
  if (Option.isNone(decoded)) return undefined;
  const preference = decoded.value;
  return preference.version === ANALYTICS_NOTICE_VERSION &&
    preference.issuedAt <= now &&
    preference.expiresAt > now &&
    preference.expiresAt - preference.issuedAt <= lifetime
    ? preference
    : undefined;
};

/** Server-side check; request headers are opt-out signals, never proof of consent. */
export const hasAnalyticsConsent = (
  cookie: string,
  headers: Readonly<Record<string, string | undefined>> = {},
) =>
  analyticsPreference(cookie)?.choice === "accepted" &&
  headers.dnt !== "1" &&
  headers.dnt !== "yes" &&
  headers["sec-gpc"] !== "1";

export const browserPrivacyEnabled = () => {
  if (globalThis.navigator === undefined) return false;
  const value = Schema.decodeUnknownOption(BrowserPrivacySignals)(navigator);
  return (
    navigator.doNotTrack === "1" ||
    navigator.doNotTrack === "yes" ||
    (Option.isSome(value) && value.value.globalPrivacyControl === true)
  );
};

const browserPreference = () => {
  if (globalThis.document === undefined) return undefined;
  const cookie = Effect.runSync(
    Effect.try({
      try: () => document.cookie,
      catch: () => new Error("Analytics preference storage unavailable"),
    }).pipe(Effect.catch(() => Effect.succeed(""))),
  );
  return analyticsPreference(cookie);
};

let consentGeneration = 0;
let previousSnapshot: string | undefined;

export const analyticsConsentSnapshot = () => {
  const preference = browserPreference();
  const snapshot = browserPrivacyEnabled()
    ? "blocked"
    : preference
      ? `${preference.choice}:${preference.revision}`
      : "pending";
  if (snapshot !== previousSnapshot) {
    consentGeneration++;
    previousSnapshot = snapshot;
  }
  return snapshot;
};

export const analyticsAllowed = () =>
  analyticsConsentSnapshot().startsWith("accepted:");

/** Document-wide measurements require acceptance before navigation began. */
export const analyticsAcceptedBefore = (timestamp: number) =>
  analyticsAllowed() &&
  (browserPreference()?.issuedAt ?? Infinity) <= timestamp;

/** A queued event is invalid forever if consent changes before export. */
export const analyticsExportGuard = () => {
  const snapshot = analyticsConsentSnapshot();
  const generation = consentGeneration;
  return () =>
    snapshot.startsWith("accepted:") &&
    analyticsConsentSnapshot() === snapshot &&
    consentGeneration === generation;
};

export const saveAnalyticsPreference = (choice: "accepted" | "declined") => {
  const issuedAt = Date.now();
  const value = Schema.encodeSync(codec)({
    choice,
    revision: crypto.randomUUID(),
    version: ANALYTICS_NOTICE_VERSION,
    issuedAt,
    expiresAt: issuedAt + lifetime,
  });
  document.cookie = `${ANALYTICS_CONSENT_COOKIE}=${value}; Path=/; Max-Age=${lifetime / 1000}; SameSite=Lax${location.protocol === "https:" ? "; Secure" : ""}`;
  globalThis.dispatchEvent(new Event(changedEvent));
  return analyticsPreference(document.cookie)?.choice === choice;
};

/** Polling covers cross-tab cookie changes, expiry and browser signal changes. */
export const subscribeAnalyticsConsent = (listener: () => void) => {
  let previous = analyticsConsentSnapshot();
  const notify = () => {
    const next = analyticsConsentSnapshot();
    if (next === previous) return;
    previous = next;
    listener();
  };
  const timer = globalThis.setInterval(notify, 1000);
  globalThis.addEventListener(changedEvent, notify);
  globalThis.addEventListener("focus", notify);
  document.addEventListener("visibilitychange", notify);
  return () => {
    globalThis.clearInterval(timer);
    globalThis.removeEventListener(changedEvent, notify);
    globalThis.removeEventListener("focus", notify);
    document.removeEventListener("visibilitychange", notify);
  };
};

import { Context, Effect, Schema } from "effect";
import type { HttpServerRequest } from "effect/http";

export interface OtlpLogsResult {
  readonly body: Uint8Array;
  /** All records in this batch have committed to authoritative storage. */
  readonly persisted: boolean;
}

export class OtlpProcessingError extends Schema.TaggedError<OtlpProcessingError>()(
  "OtlpProcessingError",
  { status: Schema.Literals([400, 403, 409, 413, 503]) },
) {}

/** Optional processing at the existing OTLP/HTTP logs boundary. */
export class OtlpLogsProcessor extends Context.Service<
  OtlpLogsProcessor,
  {
    readonly process: (
      body: Uint8Array,
    ) => Effect.Effect<
      OtlpLogsResult,
      OtlpProcessingError,
      HttpServerRequest.HttpServerRequest
    >;
  }
>()("krakstack/opentelemetry/OtlpLogsProcessor") {}

import { Config, Effect, Layer, Option, Schema, Stream } from "effect";
import {
  FetchHttpClient,
  HttpClient,
  HttpClientRequest,
  HttpMiddleware,
  HttpRouter,
  HttpServer,
  HttpServerRequest,
  HttpServerResponse,
} from "effect/http";
import { Otlp } from "./index";
import { OtlpLogsProcessor, OtlpProcessingError } from "./processor";

export { OtlpLogsProcessor, OtlpProcessingError } from "./processor";

type OtlpSignal = "traces" | "metrics" | "logs";
type OtlpSignalConfig = Uppercase<OtlpSignal>;

const otlpProxyPaths = [
  "/api/otel/v1/traces",
  "/api/otel/v1/metrics",
  "/api/otel/v1/logs",
] as const;

const exporterConfig = (signal: OtlpSignalConfig) =>
  Config.Array(Schema.String, `OTEL_${signal}_EXPORTER`).pipe(
    Config.map((exporters) =>
      exporters.map((exporter) => exporter.toLowerCase().trim()),
    ),
    Config.withDefault<ReadonlyArray<string>>([]),
  );

interface OtlpBodyBuffer {
  chunks: Array<Uint8Array>;
  size: number;
}

const readProcessorBody = Effect.fnUntraced(function* () {
  const incoming = yield* HttpServerRequest.HttpServerRequest;
  const collected = yield* incoming.stream.pipe(
    Stream.mapError(() => new OtlpProcessingError({ status: 400 })),
    Stream.runFoldEffect(
      (): OtlpBodyBuffer => ({
        chunks: [],
        size: 0,
      }),
      (state, chunk) => {
        const size = state.size + chunk.byteLength;
        if (size > 64 * 1024)
          return Effect.fail(new OtlpProcessingError({ status: 413 }));
        state.chunks.push(chunk);
        state.size = size;
        return Effect.succeed(state);
      },
    ),
  );
  const bytes = new Uint8Array(collected.size);
  let offset = 0;
  for (const chunk of collected.chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return bytes;
});

const proxyOtlp = (
  baseUrl: URL,
  signal: OtlpSignal,
  processor: Option.Option<OtlpLogsProcessor["Service"]>,
) =>
  Effect.gen(function* () {
    const incoming = yield* HttpServerRequest.HttpServerRequest;
    const client = yield* HttpClient.HttpClient;
    const contentType = incoming.headers["content-type"] ?? "application/json";
    const processLogs = signal === "logs" && Option.isSome(processor);
    if (
      processLogs &&
      contentType.split(";", 1)[0]?.trim().toLowerCase() !== "application/json"
    ) {
      return HttpServerResponse.empty({ status: 415 });
    }
    const bytes = processLogs
      ? yield* readProcessorBody()
      : new Uint8Array(yield* incoming.arrayBuffer);
    const processed = processLogs
      ? yield* processor.value.process(bytes)
      : { body: bytes, persisted: false };
    const request = HttpClientRequest.get(baseUrl).pipe(
      HttpClientRequest.appendUrl(`/v1/${signal}`),
      HttpClientRequest.setMethod("POST"),
      HttpClientRequest.bodyUint8Array(processed.body, contentType),
    );
    const forward = Effect.gen(function* () {
      const upstream = yield* client.execute(request);
      const responseBody = new Uint8Array(yield* upstream.arrayBuffer);

      if (processed.persisted) {
        if (upstream.status < 200 || upstream.status >= 300)
          yield* Effect.logWarning("Collector rejected persisted analytics", {
            status: upstream.status,
          });
        return HttpServerResponse.jsonUnsafe({});
      }
      return HttpServerResponse.uint8Array(responseBody, {
        status: upstream.status,
        contentType: upstream.headers["content-type"],
        headers: {
          "retry-after": upstream.headers["retry-after"],
        },
      });
    });
    if (!processed.persisted) return yield* forward;
    return yield* forward.pipe(
      Effect.timeout("5 seconds"),
      Effect.catch((error) =>
        Effect.logWarning(
          "Collector delivery failed after analytics commit",
          error,
        ).pipe(Effect.as(HttpServerResponse.jsonUnsafe({}))),
      ),
    );
  }).pipe(
    Effect.withTracerEnabled(false),
    HttpMiddleware.withLoggerDisabled,
    Effect.catchTag("OtlpProcessingError", (error) =>
      Effect.succeed(HttpServerResponse.empty({ status: error.status })),
    ),
    Effect.catch((error) =>
      Effect.logError("Failed to proxy browser telemetry", error).pipe(
        Effect.as(HttpServerResponse.empty({ status: 502 })),
      ),
    ),
    Effect.provide(FetchHttpClient.layer),
  );

const otlpProxyLayer = Layer.unwrap(
  Effect.gen(function* () {
    yield* Otlp;
    const baseUrl = yield* Config.URL("OTEL_EXPORTER_OTLP_ENDPOINT");
    const processor = yield* Effect.serviceOption(OtlpLogsProcessor);
    const exporters = yield* Config.all({
      logs: exporterConfig("LOGS"),
      metrics: exporterConfig("METRICS"),
      traces: exporterConfig("TRACES"),
    });

    return Layer.mergeAll(
      exporters.traces.includes("otlp")
        ? HttpRouter.add(
            "POST",
            otlpProxyPaths[0],
            proxyOtlp(baseUrl, "traces", processor),
          )
        : Layer.empty,
      exporters.metrics.includes("otlp")
        ? HttpRouter.add(
            "POST",
            otlpProxyPaths[1],
            proxyOtlp(baseUrl, "metrics", processor),
          )
        : Layer.empty,
      exporters.logs.includes("otlp")
        ? HttpRouter.add(
            "POST",
            otlpProxyPaths[2],
            proxyOtlp(baseUrl, "logs", processor),
          )
        : Layer.empty,
    );
  }),
);

const serverServices = HttpServer.layerServices.pipe(
  Layer.provideMerge(HttpMiddleware.layerTracerDisabledForUrls(otlpProxyPaths)),
);

export class HttpApiOtlp {
  static readonly layer = Layer.mergeAll(otlpProxyLayer, serverServices);
}

import { Effect, FiberSet, Layer, Predicate, Schema, Stream } from "effect";
import { FetchHttpClient, HttpClientRequest } from "effect/http";
import {
  type Otlp,
  OtlpExporter,
  OtlpLogger,
  OtlpMetrics,
  OtlpSerialization,
  OtlpTracer,
} from "effect/observability";

import { OtlpEvents, event, type EventExportOptions } from "./events";

export type { EventAttributes, EventOptions } from "./schema";

class BrowserReportedError extends Schema.TaggedError<BrowserReportedError>()(
  "BrowserReportedError",
  {
    type: Schema.Literals(["window.error", "unhandledrejection"]),
    message: Schema.String,
    stack: Schema.optional(Schema.String),
  },
) {}

const reportBrowserException = (exception: BrowserReportedError) => {
  const sanitized = sanitizeBrowserException(exception);
  return Effect.fail(
    new BrowserReportedError({ type: exception.type, ...sanitized }),
  ).pipe(
    Effect.withSpan("browser.exception", {
      root: true,
      sampled: true,
      attributes: {
        "exception.type": exception.type,
        "exception.message": sanitized.message,
        "exception.stacktrace": sanitized.stack ?? "",
      },
    }),
    Effect.ignoreCause,
  );
};

/** Essential diagnostics omit arbitrary messages, functions, URL queries and directories. */
export const sanitizeBrowserException = (input: {
  readonly type: string;
  readonly stack?: string;
}) => ({
  message:
    input.type === "window.error"
      ? "Browser error"
      : "Unhandled promise rejection",
  stack: input.stack
    ?.split("\n")
    .slice(1, 21)
    .flatMap((line) => {
      const match = line.match(/([a-zA-Z0-9_.-]+\.(?:m?js|tsx?)):(\d+):(\d+)/);
      return match ? [`${match[1]}:${match[2]}:${match[3]}`] : [];
    })
    .join("\n"),
});

const BrowserExceptionTrackingLive = Layer.effectDiscard(
  Stream.merge(
    Stream.fromEventListener<ErrorEvent>(globalThis, "error", {
      bufferSize: 100,
    }).pipe(
      Stream.map((event) => {
        const error: unknown = event.error;
        return new BrowserReportedError({
          type: "window.error",
          message: event.message,
          stack: Predicate.isError(error) ? error.stack : undefined,
        });
      }),
    ),
    Stream.fromEventListener<PromiseRejectionEvent>(
      globalThis,
      "unhandledrejection",
      { bufferSize: 100 },
    ).pipe(
      Stream.map((event) => {
        const reason: unknown = event.reason;
        return new BrowserReportedError(
          Predicate.isError(reason)
            ? {
                type: "unhandledrejection",
                message: reason.message,
                stack: reason.stack,
              }
            : {
                type: "unhandledrejection",
                message: "Unhandled promise rejection",
              },
        );
      }),
    ),
  ).pipe(Stream.runForEach(reportBrowserException), Effect.forkScoped),
);

const BrowserLifecycleFlushingLive = Layer.effectDiscard(
  Effect.gen(function* () {
    const flusher = yield* OtlpExporter.Flusher;
    const fibers = yield* FiberSet.make();
    const run = yield* FiberSet.runtime(fibers)();
    const flush = () => {
      run(
        flusher.flush.pipe(
          Effect.provideService(FetchHttpClient.RequestInit, {
            keepalive: true,
          }),
        ),
      );
    };
    const onVisibilityChange = () => {
      if (document.visibilityState === "hidden") flush();
    };

    yield* Effect.acquireRelease(
      Effect.sync(() => {
        document.addEventListener("visibilitychange", onVisibilityChange);
        globalThis.addEventListener("pagehide", flush);
      }),
      () =>
        Effect.sync(() => {
          document.removeEventListener("visibilitychange", onVisibilityChange);
          globalThis.removeEventListener("pagehide", flush);
        }),
    );
  }),
);

type OtlpOptions = Parameters<typeof Otlp.layerJson>[0];

type SignalOptions<Options> = Omit<Options, "url" | "resource" | "headers">;

export interface BrowserOtlpOptions {
  readonly serviceName: string;
  readonly serviceVersion?: string;
  readonly attributes?: NonNullable<OtlpOptions["resource"]>["attributes"];
  readonly baseUrl?: string;
  readonly headers?: OtlpOptions["headers"];
  readonly traces?:
    | false
    | SignalOptions<Parameters<typeof OtlpTracer.layer>[0]>;
  readonly metrics?:
    | false
    | SignalOptions<Parameters<typeof OtlpMetrics.layer>[0]>;
  readonly logs?: false | SignalOptions<Parameters<typeof OtlpLogger.layer>[0]>;
  /** Named OTLP log events; no automatic page tracking or analytics enrichment. */
  readonly events?: false | EventExportOptions;
}

export class BrowserOtlp {
  static readonly event = event;

  static readonly layer = ({
    attributes,
    baseUrl = "/api/otel",
    logs = false,
    events = {},
    metrics = false,
    serviceName,
    serviceVersion,
    traces = {},
    headers,
  }: BrowserOtlpOptions) => {
    const eventOptions = events === false ? undefined : events;
    const resource = { attributes, serviceName, serviceVersion };
    const request = HttpClientRequest.get(baseUrl);
    const signalUrl = (signal: "logs" | "metrics" | "traces") =>
      HttpClientRequest.appendUrl(request, `/v1/${signal}`).url;
    const exporters = Layer.mergeAll(
      OtlpExporter.layerFlusher,
      events !== false
        ? OtlpEvents.layer({
            exportInterval: "30 seconds",
            maxBatchSize: 100,
            shutdownTimeout: "3 seconds",
            ...eventOptions,
            url: signalUrl("logs"),
            resource,
            headers,
          })
        : OtlpEvents.disabledLayer,
      traces !== false
        ? OtlpTracer.layer({
            exportInterval: "30 seconds",
            ...traces,
            url: signalUrl("traces"),
            resource,
            headers,
          })
        : Layer.empty,
      metrics !== false
        ? OtlpMetrics.layer({
            exportInterval: "60 seconds",
            ...metrics,
            url: signalUrl("metrics"),
            resource,
            headers,
          })
        : Layer.empty,
      logs !== false
        ? OtlpLogger.layer({
            excludeLogSpans: true,
            mergeWithExisting: true,
            ...logs,
            url: signalUrl("logs"),
            resource,
            headers,
          })
        : Layer.empty,
    ).pipe(
      Layer.provideMerge(OtlpExporter.layerFlusher),
      Layer.provide(OtlpSerialization.layerJson),
      Layer.provide(FetchHttpClient.layer),
    );

    return Layer.mergeAll(
      BrowserLifecycleFlushingLive,
      traces !== false ? BrowserExceptionTrackingLive : Layer.empty,
    ).pipe(Layer.provideMerge(exporters));
  };
}

import { Config, Context, Effect, Layer, Schema } from "effect";
import { FetchHttpClient } from "effect/http";
import {
  Otlp as EffectOtlp,
  OtlpExporter,
  OtlpResource,
  OtlpSerialization,
} from "effect/observability";

import { OtlpEvents, event } from "./events";

export type { EventAttributes, EventOptions } from "./schema";

const ServerEventsLive = Layer.unwrap(
  Effect.gen(function* () {
    const disabled = yield* Config.Boolean("OTEL_SDK_DISABLED").pipe(
      Config.withDefault(false),
    );
    const exporters = yield* Config.Array(
      Schema.String,
      "OTEL_LOGS_EXPORTER",
    ).pipe(Config.withDefault<ReadonlyArray<string>>([]));
    if (
      disabled ||
      !exporters.some((value) => value.trim().toLowerCase() === "otlp")
    ) {
      return OtlpEvents.disabledLayer;
    }
    const endpoint = yield* Config.URL("OTEL_EXPORTER_OTLP_LOGS_ENDPOINT").pipe(
      Config.orElse(() =>
        Config.URL("OTEL_EXPORTER_OTLP_ENDPOINT").pipe(
          Config.map((url) => {
            url.pathname += `${url.pathname.endsWith("/") ? "" : "/"}v1/logs`;
            return url;
          }),
        ),
      ),
      Config.withDefault(undefined),
    );
    if (!endpoint) {
      return OtlpEvents.disabledLayer;
    }
    const headersConfig = (name: string) =>
      Config.Record(Schema.String, Schema.StringFromUriComponent, name);
    const headers = yield* headersConfig(
      "OTEL_EXPORTER_OTLP_LOGS_HEADERS",
    ).pipe(
      Config.orElse(() => headersConfig("OTEL_EXPORTER_OTLP_HEADERS")),
      Config.withDefault(undefined),
    );
    return OtlpEvents.layer({
      url: endpoint.toString(),
      headers,
      exportInterval: "1 second",
      maxBatchSize: 1000,
      shutdownTimeout: "3 seconds",
    });
  }).pipe(Effect.orDie),
);

/** Runtime-neutral server telemetry for HTTP applications, workers, and CLIs. */
export class Otlp extends Context.Service<
  Otlp,
  {
    readonly resource: Effect.Effect<OtlpResource.Resource>;
  }
>()("krakstack/opentelemetry/Otlp") {
  static readonly event = event;

  static readonly layer = Layer.mergeAll(
    Layer.succeed(this, { resource: OtlpResource.fromConfig() }),
    EffectOtlp.layerFromConfig(),
    ServerEventsLive,
  ).pipe(
    Layer.provideMerge(OtlpExporter.layerFlusher),
    Layer.provide(OtlpSerialization.layerJson),
    Layer.provide(FetchHttpClient.layer),
  );
}

import {
  Clock,
  Context,
  DateTime,
  Effect,
  Layer,
  Option,
  References,
  Schema,
} from "effect";
import {
  OtlpExporter,
  OtlpResource,
  OtlpSerialization,
} from "effect/observability";

import {
  TelemetryEvent,
  type EventAttributes,
  type EventOptions,
} from "./schema";

type ExporterOptions = Pick<
  Parameters<typeof OtlpExporter.make>[0],
  "url" | "headers" | "exportInterval" | "maxBatchSize" | "shutdownTimeout"
> & {
  readonly resource?: Parameters<typeof OtlpResource.fromConfig>[0];
  readonly scopeName?: string;
};

export type EventExportOptions = Partial<
  Pick<ExporterOptions, "exportInterval" | "maxBatchSize" | "shutdownTimeout">
>;

export class OtlpEvents extends Context.Service<
  OtlpEvents,
  { readonly push: (record: EventRecord) => void }
>()("krakstack/opentelemetry/Events") {
  static readonly disabledLayer = Layer.succeed(this, { push: () => {} });

  static readonly layer = (options: ExporterOptions) =>
    Layer.effect(
      this,
      Effect.gen(function* () {
        const serialization = yield* OtlpSerialization.OtlpSerialization;
        const resource = yield* OtlpResource.fromConfig(options.resource);
        return yield* OtlpExporter.make({
          ...options,
          label: "OtlpEvents",
          body: (logRecords: Array<EventRecord>) => {
            const scopes = new Map<string, Array<EventRecord>>();
            for (const { scopeName, canExport, ...record } of logRecords) {
              if (canExport && !canExport()) continue;
              const name = scopeName ?? options.scopeName ?? "krakstack.events";
              const records = scopes.get(name);
              if (records) records.push(record);
              else scopes.set(name, [record]);
            }
            return [
              serialization.logs({
                resourceLogs: [
                  {
                    resource,
                    scopeLogs: Array.from(scopes, ([name, records]) => ({
                      scope: { name },
                      logRecords: records,
                    })),
                  },
                ],
              }),
              Effect.void,
            ];
          },
        });
      }),
    );
}

interface EventRecord {
  /** Local-only revocation check; never serialized into OTLP. */
  readonly canExport?: () => boolean;
  readonly scopeName?: string;
  readonly eventName: string;
  readonly timeUnixNano: string;
  readonly observedTimeUnixNano: string;
  readonly severityNumber: 9;
  readonly attributes: ReturnType<typeof OtlpResource.entriesToAttributes>;
  readonly droppedAttributesCount: 0;
  readonly traceId?: string;
  readonly spanId?: string;
}

/** Emits an INFO event without creating a tracing span or persisting identity. */
export const event = Effect.fnUntraced(function* (
  name: string,
  properties?: EventAttributes,
  options?: EventOptions,
) {
  const decoded = yield* Schema.decodeUnknownEffect(TelemetryEvent)({
    name,
    properties,
    options,
  });
  const events = yield* OtlpEvents;
  const clock = yield* Clock.Clock;
  const observedTime = clock.currentTimeNanosUnsafe().toString();
  const timestamp = decoded.options?.timestamp
    ? (
        BigInt(DateTime.toEpochMillis(decoded.options.timestamp)) * 1_000_000n
      ).toString()
    : observedTime;
  const span = yield* Effect.currentSpan.pipe(Effect.option);
  const attributes = { ...decoded.options?.context, ...decoded.properties };
  if (decoded.options?.userId) attributes["user.id"] = decoded.options.userId;
  if (decoded.options?.anonymousId)
    attributes["analytics.anonymous_id"] = decoded.options.anonymousId;
  if (decoded.options?.sessionId)
    attributes["session.id"] = decoded.options.sessionId;
  if (decoded.options?.messageId)
    attributes["log.record.uid"] = decoded.options.messageId;
  const annotations = yield* References.CurrentLogAnnotations;
  events.push({
    eventName: decoded.name,
    timeUnixNano: timestamp,
    observedTimeUnixNano: observedTime,
    severityNumber: 9,
    attributes: OtlpResource.entriesToAttributes(
      Object.entries({
        ...attributes,
        ...annotations,
      }),
    ),
    droppedAttributesCount: 0,
    traceId: Option.isSome(span) ? span.value.traceId : undefined,
    spanId: Option.isSome(span) ? span.value.spanId : undefined,
  });
});

import { Schema } from "effect";

export const BrowserAnalyticsPreference = Schema.Struct({
  version: Schema.String,
  choice: Schema.Literals(["accepted", "declined"]),
  /** A consent revision, not a visitor identifier; never exported with telemetry. */
  revision: Schema.String,
  issuedAt: Schema.Finite,
  expiresAt: Schema.Finite,
}).annotate({ identifier: "BrowserAnalyticsPreference" });

export const BrowserPrivacySignals = Schema.Struct({
  globalPrivacyControl: Schema.optional(Schema.Boolean),
}).annotate({ identifier: "BrowserPrivacySignals" });

export const BrowserWebVital = Schema.Struct({
  name: Schema.Literals(["LCP", "INP", "CLS", "FCP", "TTFB"]),
  id: Schema.NonEmptyString.check(Schema.isMaxLength(64)),
  value: Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0)),
  delta: Schema.Finite,
  rating: Schema.Literals(["good", "needs-improvement", "poor"]),
  navigationType: Schema.Literals([
    "navigate",
    "reload",
    "back-forward",
    "back-forward-cache",
    "prerender",
    "restore",
  ]),
}).annotate({ identifier: "BrowserWebVital" });

const EventAttributeValue = Schema.Union([
  Schema.String,
  Schema.Finite,
  Schema.Boolean,
  Schema.Array(Schema.String),
  Schema.Array(Schema.Finite),
  Schema.Array(Schema.Boolean),
]);

export const EventAttributesSchema = Schema.Record(
  Schema.String,
  EventAttributeValue,
).annotate({ identifier: "EventAttributes" });

export const EventOptionsSchema = Schema.Struct({
  userId: Schema.optional(Schema.NonEmptyString),
  anonymousId: Schema.optional(Schema.NonEmptyString),
  sessionId: Schema.optional(Schema.NonEmptyString),
  messageId: Schema.optional(Schema.NonEmptyString),
  timestamp: Schema.optional(Schema.DateTimeUtc),
  context: Schema.optional(EventAttributesSchema),
}).annotate({ identifier: "EventOptions" });

export const TelemetryEvent = Schema.Struct({
  name: Schema.NonEmptyString,
  properties: Schema.optional(EventAttributesSchema),
  options: Schema.optional(EventOptionsSchema),
}).annotate({ identifier: "TelemetryEvent" });

export type EventAttributes = typeof EventAttributesSchema.Type;
export type EventOptions = typeof EventOptionsSchema.Type;

import { onCLS, onFCP, onINP, onLCP, onTTFB, type Metric } from "web-vitals";
import { Clock, Context, Effect, Layer, Schema } from "effect";
import { OtlpEvents } from "./events";
import { BrowserWebVital } from "./schema";
import {
  analyticsAcceptedBefore,
  analyticsExportGuard,
  browserPrivacyEnabled,
  subscribeAnalyticsConsent,
} from "./consent";

const subscribers = new Set<(metric: Metric) => void>();
let started = false;

/** web-vitals observers are document-scoped; only subscribers retain application state. */
export const subscribeWebVitals = (subscriber: (metric: Metric) => void) => {
  subscribers.add(subscriber);
  if (!started) {
    started = true;
    const report = (metric: Metric) => {
      for (const listener of subscribers) listener(metric);
    };
    onCLS(report);
    onFCP(report);
    onINP(report);
    onLCP(report);
    onTTFB(report);
  }
  return () => {
    subscribers.delete(subscriber);
  };
};

export const WebVitals = Context.Reference<{
  readonly subscribe: typeof subscribeWebVitals;
}>("krakstack/opentelemetry/WebVitals", {
  defaultValue: () => ({ subscribe: subscribeWebVitals }),
});

/** https://opentelemetry.io/docs/specs/semconv/browser/browser-events/ */
const WebVitalsLive = (requireConsent: boolean, respectDoNotTrack: boolean) =>
  Layer.effectDiscard(
    Effect.gen(function* () {
      const vitals = yield* WebVitals;
      const events = yield* OtlpEvents;
      const clock = yield* Clock.Clock;
      const seen = new Map<string, number>();
      // Buffered metrics describe the whole document, not just time after acceptance.
      if (requireConsent && !analyticsAcceptedBefore(performance.timeOrigin))
        return;
      const consentGuard = requireConsent ? analyticsExportGuard() : () => true;
      let active = true;
      const canExport = () => {
        active =
          active &&
          consentGuard() &&
          (!respectDoNotTrack || !browserPrivacyEnabled());
        return active;
      };
      if (!canExport()) return;
      yield* Effect.acquireRelease(
        Effect.sync(() => {
          const report = (input: Metric) => {
            if (!canExport()) return;
            const parsed = Schema.decodeUnknownOption(BrowserWebVital)(input);
            if (parsed._tag === "None") return;
            const metric = parsed.value;
            const key = `${metric.name}:${metric.id}`;
            if (seen.get(key) === metric.value) return;
            seen.set(key, metric.value);
            const timestamp = clock.currentTimeNanosUnsafe().toString();
            events.push({
              canExport,
              eventName: "browser.web_vital",
              timeUnixNano: timestamp,
              observedTimeUnixNano: timestamp,
              severityNumber: 9,
              droppedAttributesCount: 0,
              attributes: [
                {
                  key: "browser.web_vital.name",
                  value: { stringValue: metric.name.toLowerCase() },
                },
                {
                  key: "browser.web_vital.id",
                  value: { stringValue: metric.id },
                },
                {
                  key: "browser.web_vital.value",
                  value: { doubleValue: metric.value },
                },
                {
                  key: "browser.web_vital.delta",
                  value: { doubleValue: metric.delta },
                },
                {
                  key: "browser.web_vital.rating",
                  value: { stringValue: metric.rating },
                },
                {
                  key: "browser.web_vital.navigation_type",
                  value: { stringValue: metric.navigationType },
                },
                {
                  key: "log.record.uid",
                  value: { stringValue: `${metric.id}:${metric.value}` },
                },
              ],
            });
          };
          const unsubscribe = vitals.subscribe(report);
          const stop = subscribeAnalyticsConsent(() => {
            if (!canExport()) unsubscribe();
          });
          return () => {
            stop();
            unsubscribe();
          };
        }),
        (unsubscribe) => Effect.sync(unsubscribe),
      );
    }),
  );

export interface BrowserWebVitalsOptions {
  readonly requireConsent?: boolean;
  readonly respectDoNotTrack?: boolean;
}

export class BrowserWebVitals {
  /** Provide a browser telemetry layer with events enabled; no exporter is created here. */
  static readonly layer = ({
    respectDoNotTrack = true,
    requireConsent = true,
  }: BrowserWebVitalsOptions = {}) =>
    WebVitalsLive(requireConsent, respectDoNotTrack);
}
